async function exported(source,n,save){const p=await browser.newPage({viewport:{width:2080,height:600}});await p.goto(pathToFileURL(path.join(source,'index.html')).href+'#floor='+n);await p.locator('#scheduleDate').fill('2027-06-28');await p.locator('#scheduleDate').dispatchEvent('change');await p.locator('#floorNav button').filter({hasText:new RegExp('^'+n+'$')}).click();const svg=await p.locator('#map').evaluate((s,n)=>{const c=s.cloneNode(true),a=[s,...s.querySelectorAll('*')],b=[c,...c.querySelectorAll('*')];a.forEach((o,i)=>{const st=getComputedStyle(o);for(const k of ['fill','stroke','stroke-width','stroke-dasharray','opacity','font-family','font-size','font-weight','text-anchor','pointer-events'])b[i].style.setProperty(k,st.getPropertyValue(k));});c.setAttribute('width','2080');c.setAttribute('height','440');c.setAttribute('viewBox',n===1?'-20 -15 1040 220':'-30 -45 1100 285');c.setAttribute('xmlns','http://www.w3.org/2000/svg');c.style='width:2080px;height:440px';return c.outerHTML;},n);await p.setContent('<body style="margin:0">'+svg+'</body>');const png=await p.locator('svg').screenshot({omitBackground:true});if(save){fs.writeFileSync(path.join(out,'floor'+n+'.svg'),svg);fs.writeFileSync(path.join(out,'floor'+n+'.png'),png);}await p.close();return png;}
