const root=path.resolve(__dirname,'..'),hash=b=>crypto.createHash('sha256').update(b).digest('hex');
// Git normalizes CRLF on add/checkout. Restore only the recorded line endings;
// content and line counts still have to match the exact historical byte gates.
function recordedBytes(file,bytes){const m=require('../ROOM-01C_CHANGES.json'),runs=m.currentLineEndings[file];assert.ok(runs,file+' recorded line endings');const text=bytes.toString('utf8').replaceAll('\r\n','\n');assert.equal(text.split('\n').length-1,runs.reduce((n,r)=>n+r.count,0),file+' recorded line count');let run=0,left=runs[0]?.count||0;return Buffer.from(text.replace(/\n/g,()=>{while(!left){run++;left=runs[run].count;}left--;return runs[run].eol;}),'utf8');}
function baselineBytes(file){let text=recordedBytes(file,fs.readFileSync(path.join(root,file))).toString('utf8');const m=require('../ROOM-01C_CHANGES.json');for(const p of [...(m.sourcePatches[file]||[])].reverse()){assert.equal(text.split(p.new).length,2,file+' unique ROOM-01C hunk');text=text.replace(p.new,()=>p.old);}return Buffer.from(text,'utf8');}
function baselineModule(file){const localModule={exports:{}};Function('module','window','globalThis',baselineBytes(file).toString('utf8'))(localModule,undefined,{});return localModule.exports;}
function validatePreservation(){const m=require('../ROOM-01C_CHANGES.json');assert.equal(m.baselineCommit,'573d0e168ebc7de88a55f8589c3d37a7ca404693');assert.equal(m.userContractSha256,'431afa9788ea79ec9bd98631f074e4d9ed231dc242f94486da3ed93795c2d346');assert.deepEqual(Object.keys(m.currentLineEndings).sort(),Object.keys(m.baselineFiles).sort());assert.deepEqual(Object.keys(m.sourcePatches).sort(),['README.md','index.html','map-semantics.js','room-identification.js','tests/geo02-browser.cjs','tests/room01-browser.cjs','tests/room01b-browser.cjs','tests/room01b-contract.cjs'].sort());for(const [file,h] of Object.entries(m.baselineFiles))assert.equal(hash(baselineBytes(file)),h.sha256,file+' exact pre-C bytes');return {protectedFiles:Object.keys(m.baselineFiles).length,changedFiles:Object.keys(m.sourcePatches)};}

